// Display bands for a single Calling's affinity.
export const BANDS = [
  { at: 80, label: 'Dominant', meaning: 'Very strong expression of the motive; usually central to the result.' },
  { at: 62.5, label: 'Strong', meaning: 'Potentially archetype-defining if within 15 points of the highest score.' },
  { at: 45, label: 'Present', meaning: 'Meaningful capacity exists, but it does not automatically qualify as archetype-defining.' },
  { at: 25, label: 'Subdued', meaning: 'Present in some contexts but usually secondary to other motives.' },
  { at: 0, label: 'Quiet', meaning: 'This motive is usually not a primary organizing force.' },
];

export const bandOf = (affinity) =>
  (BANDS.find((b) => affinity >= b.at) || BANDS[BANDS.length - 1]);

